@RestController
@RequestMapping("/api/documents")
public class DocumentController {

    // RBAC Example using Spring Security @PreAuthorize
    @GetMapping("/{id}")
    @PreAuthorize("hasRole('ADMIN') or hasAuthority('DOCUMENT_READ')")
    public ResponseEntity<Document> getDocumentRbac(@PathVariable Long id) {
        return ResponseEntity.ok(documentService.findById(id));
    }

    // ABAC Example evaluating dynamic attributes using SpEL
    @PutMapping("/{id}")
    @PreAuthorize("@abacEvaluator.canAccess(#id, principal, 'UPDATE')")
    public ResponseEntity<Document> updateDocumentAbac(@PathVariable Long id, @RequestBody DocumentDto dto) {
        return ResponseEntity.ok(documentService.update(id, dto));
    }
}
